mapper.select:
SELECT * FROM chat_message
WHERE room_id = #{roomId}
ORDER BY timestamp ASC

SELECT COUNT(*) > 0
FROM chat_room_member
WHERE user_id = #{userId}
  AND room_id = #{roomId}

mapper.update:
UPDATE chat_message
SET is_read = TRUE
WHERE room_id = #{roomId}
  AND sender_id != #{userId}
  AND is_read = FALSE

UPDATE chat_room_member
SET last_read_message_id = (SELECT MAX(message_id) FROM chat_message WHERE room_id = #{roomId})
WHERE room_id = #{roomId} AND user_id = #{userId}

mapper.select:
SELECT MIN(COALESCE(last_read_message_id, 0))
FROM chat_room_member
WHERE room_id = #{roomId} AND user_id != #{userId}
